  "{ \"ops\": [",
  "  { \"op\": \"deleteSlide\", \"slide\": 5 },",
  "  { \"op\": \"reorderSlides\", \"order\": [1, 3, 2, 4] },",
  "  { \"op\": \"duplicateSlide\", \"slide\": 2, \"after\": 4 },",
  "  { \"op\": \"insertSlide\", \"layout\": \"Title and Content\", \"after\": 4,",
